from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def can_construct(ransom_note: str, magazine: str) -> bool:
    stock = Counter(magazine)
    for ch in ransom_note:
        if stock[ch] == 0:
            return False
        stock[ch] -= 1
    return True
